effect.shader:
float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

void main() {
    vec2 uv = acScreenNorm;
    vec4 base = texture(inputImg, uv);
    float cx = 1.0 / acResolution.x;
    float cy = 1.0 / acResolution.y;
    float L0 = luma(base.rgb) * base.a;

    float glow = 0.0;
    float r = width;
    for (int i = -3; i <= 3; i++) {
        for (int j = -3; j <= 3; j++) {
            if (i == 0 && j == 0) continue;
            vec2 o = vec2(float(i), float(j)) * r / 3.0;
            vec4 s = texture(inputImg, uv + vec2(o.x * cx, o.y * cy));
            float ls = luma(s.rgb) * s.a;
            float edge = max(0.0, ls - threshold);
            float dist = length(o);
            float w = exp(-dist * dist / (r * r * (0.2 + softness)));
            glow += edge * w;
        }
    }
    glow = clamp(glow * intensity / 24.0, 0.0, 4.0);

    vec3 outRgb = base.rgb + color.rgb * glow;
    fragColor = vec4(outRgb, max(base.a, min(1.0, glow)));
}
